",e(a,{template:"react-ts",files:{"/App.tsx":'import { useState } from "react";

interface ProcessingStep {
name: string;
status: "waiting" | "processing" | "complete";
}

const steps: ProcessingStep[] = [
{ name: "Upload to S3", status: "complete" },
{ name: "Trigger Lambda", status: "complete" },
{ name: "Resize Image", status: "complete" },
{ name: "Compress", status: "complete" },
{ name: "Generate Thumbnails", status: "complete" },
{ name: "Save to Output Bucket", status: "complete" },
];

export default function App() {
const [uploaded, setUploaded] = useState(false);
const [processing, setProcessing] = useState(false);
const [complete, setComplete] = useState(false);

const handleUpload = () => {
  setUploaded(true);
  setProcessing(true);
  setTimeout(() => {
    setProcessing(false);
    setComplete(true);
  }, 2000);
};

return (
  <div style={{ padding: "20px", fontFamily: "system-ui" }}>
    <h1>Serverless Image Processing</h1>
    <p>Click to simulate an image upload through the pipeline</p>

    {!uploaded ? (
      <button 
        onClick={handleUpload}
        style={{
          marginTop: "20px",
          padding: "12px 24px",
          fontSize: "16px",
          background: "#3b82f6",
          color: "white",
          border: "none",
          borderRadius: "8px",
          cursor: "pointer"
        }}
      >
        Upload Image
      </button>
    ) : (
      <div style={{ marginTop: "20px" }}>
        {steps.map((step, index) => (
          <div 
            key={step.name}
            style={{
              display: "flex",
              alignItems: "center",
              marginBottom: "10px",
              padding: "10px",
              background: complete ? "#f0fdf4" : "#f9fafb",
              borderRadius: "8px",
              border: "1px solid #e5e7eb"
            }}
          >
            <div style={{
              width: "24px",
              height: "24px",
              borderRadius: "50%",
              background: complete ? "#22c55e" : "#6b7280",
              color: "white",
              display: "flex",
              alignItems: "center",
              justifyContent: "center",
              marginRight: "12px",
              fontSize: "12px"
            }}>
              {complete ? "✓" : index + 1}
            </div>
            <span style={{ 
              color: complete ? "#166534" : "#374151",
              fontWeight: complete ? "600" : "400"
            }}>
              {step.name}
            </span>
            {processing && index === 2 && (
              <span style={{ marginLeft: "auto", color: "#3b82f6" }}>
                Processing...
              </span>
            )}
          </div>
        ))}
      </div>
    )}

    {complete && (
      <div style={{ marginTop: "20px", padding: "15px", background: "#dcfce7", borderRadius: "8px" }}>
        <strong>✓ Complete!</strong> Image processed and saved to output bucket.
      </div>
    )}
  </div>
);
